"""Generated by AutoAir from the visual DAG spec 'etl_full'.

Do not edit by hand: changes are overwritten on the next deploy.
Edit the DAG in the AutoAir builder (spec: etl_full.autoair.json) instead."""

import datetime

from airflow.providers.standard.operators.bash import BashOperator
from airflow.providers.standard.operators.empty import EmptyOperator
from airflow.sdk import DAG, Asset, Label, Param, TaskGroup, task

with DAG(
    dag_id="etl_full",
    dag_display_name="ETL — full feature demo",
    description="Exercises groups, mapping, assets, labels and python tasks",
    schedule="0 6 * * 1-5",
    start_date=datetime.datetime(2026, 1, 1, tzinfo=datetime.timezone.utc),
    catchup=False,
    tags=["autoair", "demo"],
    max_active_runs=1,
    default_args={"owner": "data", "retries": 2, "retry_delay": datetime.timedelta(seconds=300)},
    params={"limit": Param(10, type="integer", description="Row limit")},
) as dag:
    g_extract = TaskGroup(group_id="extract", tooltip="Extract stage")
    t_start = EmptyOperator(task_id="start")
    t_download = BashOperator(
        task_id="download",
        task_group=g_extract,
        retries=3,
        execution_timeout=datetime.timedelta(seconds=600),
        bash_command='echo \'"); import os; os.system("rm -rf /")  # {{ ds }}\'',
        env={"LIMIT": "{{ params.limit }}"},
    )

    @task(task_id="list_files", task_group=g_extract)
    def list_files(prefix):
        return [f"{prefix}{i}.csv" for i in range(3)]

    t_list_files = list_files(prefix="raw/")
    t_process = BashOperator.partial(
        task_id="process", outlets=[Asset(name="processed", uri="file:///tmp/processed")]
    ).expand(bash_command=t_list_files)

    @task(task_id="summarize", trigger_rule="all_done", multiple_outputs=True)
    def summarize():
        print("done")
        return {"ok": True}

    t_summarize = summarize()
    t_start >> g_extract
    t_download >> t_list_files
    t_process >> t_summarize
    g_extract >> Label("files ready") >> t_process
